import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CCZdR_Jo.js";const l="/aibutler/docs-versions/v1.1.3/img/persona-quick-create.png",g=JSON.parse('{"title":"人格","description":"","frontmatter":{},"headers":[],"relativePath":"guide/persona.md","filePath":"guide/persona.md"}'),i={name:"guide/persona.md"};function s(n,t,d,p,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="人格" tabindex="-1">人格 <a class="header-anchor" href="#人格" aria-label="Permalink to &quot;人格&quot;">​</a></h1><p>人格就是你的 AI 助手。每个人格有自己的名字、头像、记忆和模型，互不干扰。你可以建好几个：一个管工作，一个陪孩子学习，一个帮你盯投资。</p><h2 id="建一个新人格" tabindex="-1">建一个新人格 <a class="header-anchor" href="#建一个新人格" aria-label="Permalink to &quot;建一个新人格&quot;">​</a></h2><p>点主窗口上方的「人格 ▾」→「＋ 新建人格…」。</p><p><strong>最省事的办法是一句话建</strong>：在新建页顶上的「一句话建人格」里写一句它是做什么的，比如「教我做家常菜的厨师，菜谱要简单」，点「让管家去建」。管家会定好名字、头像和定位，直接建出来，建完告诉你它定了什么。</p><p><img src="'+l+'" alt="新建页顶上的「一句话建人格」"></p><p>想自己细调，就用下面的表单：填名字，点「创建并打开」。</p><p>「高级」里还能设：</p><ul><li><strong>目录</strong>：人格的资料放在哪。建好之后不能改，想放到别的盘，建之前在这里选。</li><li><strong>唤醒语</strong>：每次打开它时，它先看到的一句话。</li><li><strong>设为管家</strong>：管家是所有人格的中心，能帮你开、建别的人格。全局只能有一个。</li></ul><h2 id="编辑人格" tabindex="-1">编辑人格 <a class="header-anchor" href="#编辑人格" aria-label="Permalink to &quot;编辑人格&quot;">​</a></h2><p>「人格 ▾」→「⚙ 管理人格…」，在人格卡片上点「编辑」。编辑页分五块：</p><table tabindex="0"><thead><tr><th>页</th><th>管什么</th></tr></thead><tbody><tr><td>基本</td><td>名字、头像</td></tr><tr><td>AI</td><td>接入方式、引擎、模型，见 <a href="/aibutler/docs-versions/v1.1.3/guide/models.html">接入模型</a></td></tr><tr><td>身份档案</td><td>它是谁、怎么说话、有什么规矩</td></tr><tr><td>通道</td><td>Telegram、飞书、AIHUB 等，见 <a href="/aibutler/docs-versions/v1.1.3/guide/channels.html">通道</a></td></tr><tr><td>高级</td><td>不常用的设置</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">改身份档案不如直接跟它说</p><p>「以后说话简短点」「叫我老王就行」「回答先说结论」，直接对它说，它会自己记下来，比去改档案方便。</p></div><h2 id="它的记忆是怎么回事" tabindex="-1">它的记忆是怎么回事 <a class="header-anchor" href="#它的记忆是怎么回事" aria-label="Permalink to &quot;它的记忆是怎么回事&quot;">​</a></h2><p>人格有一个长期记忆库，存在你自己的电脑上。</p><ul><li><strong>你说过的事它会记下来</strong>：你的习惯、做过的决定、交代过的规矩、纠正过它的地方。</li><li><strong>它做事前会先查记忆</strong>：所以你教过一次的事，下次不用再教。</li><li><strong>你纠正它，它会改</strong>：它记错了或做错了，直接说「不对，应该是……」，它会改掉旧的那条。</li></ul><p>聊天记录太长时，人格会自己整理一下：把要紧的事写进记忆和交接单，然后清空上下文，从头接着干。所以重新打开后，它可能不记得刚才聊天的原话，但记得该记的事。想让它记住什么，就明说一句「记住：……」。</p><h2 id="导出和导入" tabindex="-1">导出和导入 <a class="header-anchor" href="#导出和导入" aria-label="Permalink to &quot;导出和导入&quot;">​</a></h2><ul><li><strong>导出</strong>：人格管理里，人格卡片的「⋯」→「导出」。整个人格变成一个文件，记忆和身份都在里面。</li><li><strong>导入</strong>：人格管理下方点「从文件导入…」，选那个文件。导入后它还是它，记忆都跟过来了。</li></ul><p>导出的文件<strong>不含</strong>：各种 Key 和 Token（导入后要重新填）、聊天原文、附件。所以发给朋友也不会泄露你的密钥。</p><p>用途：换电脑；把调教好的人格分享给朋友；备份。</p><h2 id="人格之间可以互相帮忙" tabindex="-1">人格之间可以互相帮忙 <a class="header-anchor" href="#人格之间可以互相帮忙" aria-label="Permalink to &quot;人格之间可以互相帮忙&quot;">​</a></h2><p>同一台电脑上的人格可以互相请教，比如让「研究员」查完资料交给「写手」整理。连上 <a href="/aibutler/docs-versions/v1.1.3/guide/aihub.html">AIHUB</a> 后，还能和别人电脑上的人格互发消息。</p><p>直接跟人格说就行：</p><blockquote><p>问问研究员，上周那个市场数据查到没有。</p></blockquote><h2 id="把活派到后台" tabindex="-1">把活派到后台 <a class="header-anchor" href="#把活派到后台" aria-label="Permalink to &quot;把活派到后台&quot;">​</a></h2><p>活儿多、耗时长的时候，人格可以派一个或一组帮手在后台查资料、跑命令，自己接着跟你聊，帮手做完它会回来报结果。正在跑的后台活会列在任务面板上。帮手默认用跟主模型同一家的便宜型号。</p><p>你不用专门吩咐，它觉得该分出去就会分；也可以直接说：</p><blockquote><p>你派几个帮手分头查一下这三家公司，查完汇总给我。</p></blockquote>',29)])])}const b=a(i,[["render",s]]);export{g as __pageData,b as default};
